class Solution {
    public int[] constructArray(int n, int k) {
        int[] answer = new int[n];
        int lo = 1;
        int hi = k + 1;
        for (int i = 0; i <= k; i++) {
            answer[i] = (i % 2 == 0) ? lo++ : hi--;
        }
        for (int i = k + 1; i < n; i++) {
            answer[i] = i + 1;
        }
        return answer;
    }
}

class Solution {
    public int[] constructArray(int n, int k) {
        int[] answer = new int[n];
        int index = 0;
        int prefixEnd = n - k;
        for (int value = 1; value < prefixEnd; value++) {
            answer[index++] = value;
        }

        int low = prefixEnd;
        int high = n;
        boolean takeLow = true;
        while (low <= high) {
            if (takeLow) {
                answer[index++] = low++;
            } else {
                answer[index++] = high--;
            }
            takeLow = !takeLow;
        }
        return answer;
    }
}

class Solution {
    public int[] constructArray(int n, int k) {
        int[] answer = new int[n];
        int value = 1;
        answer[0] = value;
        for (int diff = k, index = 1; diff >= 1; diff--, index++) {
            if (((k - diff) & 1) == 0) {
                value += diff;
            } else {
                value -= diff;
            }
            answer[index] = value;
        }
        for (int i = k + 1; i < n; i++) {
            answer[i] = i + 1;
        }
        return answer;
    }
}

class Solution {
    public int[] constructArray(int n, int k) {
        int[] answer = new int[n];
        int low = 1;
        int high = n;
        int remaining = k;

        for (int index = 0; index < n; index++) {
            if (remaining > 1) {
                if ((remaining & 1) == 1) {
                    answer[index] = low++;
                } else {
                    answer[index] = high--;
                }
                remaining--;
            } else {
                answer[index] = low++;
            }
        }
        return answer;
    }
}
